import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # If no features available, return empty design
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Identify strong candidates based on t-statistics and effect sizes
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            # Calculate effect size (standardized difference)
            mean_1 = feats.x[feats.y==1, i].mean()
            mean_0 = feats.x[feats.y==0, i].mean()
            std_pooled = np.sqrt(((feats.x[feats.y==1, i].size - 1) * feats.x[feats.y==1, i].var() + 
                                (feats.x[feats.y==0, i].size - 1) * feats.x[feats.y==0, i].var()) / 
                               (feats.x[feats.y==1, i].size + feats.x[feats.y==0, i].size - 2))

            if std_pooled > 0:
                effect_size = abs(mean_1 - mean_0) / std_pooled
                if effect_size > 1.0:  # Threshold for strong effect
                    candidates.append((fid, effect_size))

    # Sort by strength
    candidates.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates, avoiding near-duplicates
    selected = []
    excluded = set()
    for fid, _ in candidates:
        if fid in excluded:
            continue
        selected.append(fid)
        if len(selected) >= MAX_DRIVERS:
            break
        # Exclude correlated features
        for other_fid, _ in candidates:
            if other_fid != fid and other_fid not in excluded:
                try:
                    corr = np.corrcoef(feats.x[:, feats.column(fid)], feats.x[:, feats.column(other_fid)])[0, 1]
                    if abs(corr) > 0.6:
                        excluded.add(other_fid)
                except:
                    continue

    # If no strong candidates found, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    drivers = tuple(selected)
    columns = tuple(selected)

    # Add interaction terms for top two features if they exist
    products = []
    if len(selected) >= 2:
        products = [(selected[0], selected[1])]

    # Compute loadings using mutual information
    try:
        mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in selected]], feats.y)
        loadings = dict(zip(selected, mi_scores))
    except:
        loadings = {fid: 1.0 for fid in selected}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

